/* --- 상태: 시즌(해)마다 새로 --- */
function xmSeason(){try{return wnSeason()}catch(e){return false}}
function XM(){var s=wnSid(),o=save.xm;if(!o||typeof o!=='object'||o.s!==s)o=save.xm={s:s,an:0,ad:'',box:0,cg:[]};if(!(o.an>=0))o.an=0;if(!(o.box>=0))o.box=0;if(!Array.isArray(o.cg))o.cg=[];return o}

/* --- 전용 꾸미기: 호랑가시 왕관(선물 상자 150개 · 상점에는 안 나옴) --- */
ACC_HEAD.xm_holly=function(c,U){var lw=LW(U),i;
  c.beginPath();c.ellipse(0,-U*.12,U*.5,U*.13,0,Math.PI,Math.PI*2);c.lineWidth=U*.13;c.strokeStyle='#0B2C4A';c.stroke();c.lineWidth=U*.07;c.strokeStyle='#C9A24A';c.stroke();
  var L=[[-.42,-.2,-.9],[-.22,-.34,-.45],[.22,-.34,.45],[.42,-.2,.9]];
  L.forEach(function(q){c.save();c.translate(q[0]*U,q[1]*U);c.rotate(q[2]);c.beginPath();var w=U*.15,h=U*.36;c.moveTo(0,0);
    c.quadraticCurveTo(-w*1.3,-h*.25,-w*.6,-h*.5);c.quadraticCurveTo(-w*1.4,-h*.62,-w*.5,-h*.82);c.quadraticCurveTo(-w*.6,-h*1.02,0,-h);
    c.quadraticCurveTo(w*.6,-h*1.02,w*.5,-h*.82);c.quadraticCurveTo(w*1.4,-h*.62,w*.6,-h*.5);c.quadraticCurveTo(w*1.3,-h*.25,0,0);c.closePath();
    fo(c,lg(c,-h,0,'#5EDB6A','#1E8A3E'),lw*.85);c.beginPath();c.moveTo(0,-U*.03);c.lineTo(0,-h*.92);c.lineWidth=Math.max(1,U*.03);c.strokeStyle='rgba(11,44,74,.55)';c.stroke();c.restore()});
  for(i=-1;i<=1;i++){c.beginPath();c.arc(i*U*.12,-U*.42+(i?U*.05:0),U*.1,0,Math.PI*2);fo(c,lg(c,-U*.52,-U*.32,'#FF7A7A','#C8202E'),lw*.8);
    c.globalAlpha=.75;c.fillStyle='#fff';c.beginPath();c.arc(i*U*.12-U*.03,-U*.45+(i?U*.05:0),U*.03,0,Math.PI*2);c.fill();c.globalAlpha=1}};
ACC.push({id:'xm_holly',slot:'head',name:T('호랑가시 왕관'),c:{cur:'gems',price:0},wn:1,ex:1});
var hwListXM=hwList;hwList=function(arr,own){var r=hwListXM.apply(this,arguments);try{if(arr===ACC)r=r.filter(function(o){return o.id!=='xm_holly'||own(o)})}catch(e){}return r};

/* --- 선물 주기(덱 · 진주 · 보석 · 꾸미기) --- */
function xmGive(R){var sub='';
  if(R.d){var D=decoById(R.d),dd=DS(),W=TWW();if(D&&dd.placed.length<DECO_MAX){var nx=decoSpot(D,true);dd.placed.push({k:R.d,x:nx,y:clamp((floorAt(nx*W)+ch*.03-decoW(D,1)*decoAR(D)*.42)/ch,.25,.95),s:1,f:0});sub=T('수족관에 넣어 드렸어요')+' · '+D.name}else{dd.inv[R.d]=(dd.inv[R.d]||0)+1;sub=T('수족관 › 꾸미기 › 소품에 넣어 뒀어요')}try{refreshTank()}catch(e){}}
  if(R.p){save.pearls+=R.p;sub=T('진주 ')+'+'+nf(R.p)}
  if(R.g){save.gems+=R.g;sub=T('보석 ')+'+'+nf(R.g)}
  if(R.a){var S=AS();if(S.own.indexOf(R.a)<0)S.own.push(R.a);var Ac=accById(R.a);sub=(Ac?Ac.name:'')+' · '+T('상점 › 꾸미기에서 씌워 보세요')}
  persist();return sub}

/* --- 출석 7일(빠진 날은 건너뛰지 않고 이어서) --- */
var XM_ATT=[{d:'wn_tree'},{p:300},{a:'wn_santa'},{g:5},{a:'wn_snow'},{p:800},{g:15}];var XM_ATT_LB={wn_tree:'트리',wn_santa:'산타 모자',wn_snow:'눈 꼬리'}; /* 좁은 폰(320)에서 칸 안에 들어가게 짧은 이름 */
function xmAttCan(){if(!xmSeason())return false;var o=XM();return o.an<XM_ATT.length&&o.ad!==today()}
function xmAttClaim(){if(!xmAttCan())return;var o=XM(),i=o.an,R=XM_ATT[i];o.an++;o.ad=today();var sub=xmGive(R);crumb('xmAtt:'+o.an);try{svSnd('gem');buzz([20,30,40])}catch(e){}
  banner(o.an===1?T('크리스마스가 찾아왔어요! 🎄'):T('크리스마스 출석 선물')+' '+(LANG==='en'?'Day '+o.an:o.an+T('일째')),sub+(o.an<XM_ATT.length?' · '+T('내일 또 오면 크리스마스 선물이 이어져요'):''));
  try{refreshHome(true)}catch(e){}xmRender();xmBarPaint();try{notiPlan()}catch(e){}}

/* --- 오늘의 미션 3개 --- */
var XMM=[{k:'gift',goal:4,txt:'선물 상자 4개 먹기',p:120,c:3,ic:'gift'},{k:'boss',goal:1,txt:'루돌프 아귀 물리치기',p:150,c:5,ic:'angler'},{k:'solo',goal:3,txt:'싱글 3판 하기',p:100,c:2,ic:'solo'}];
function XMD(){var d=today(),o=XM();if(!o.m||o.m.d!==d)o.m={d:d,v:{},got:{}};return o.m}
function xmmAdd(k,n){if(!xmSeason())return;var M=XMD(),o=null;XMM.forEach(function(x){if(x.k===k)o=x});if(!o)return;var was=M.v[k]|0;M.v[k]=was+n;persist();
  if(was<o.goal&&M.v[k]>=o.goal)setTimeout(function(){banner(T('크리스마스 미션 완료!'),T(o.txt)+T(' · 크리스마스 이벤트에서 받아요'))},1100);try{xmBarPaint()}catch(e){}}
function xmmReady(o){var M=XMD();return (M.v[o.k]|0)>=o.goal&&!M.got[o.k]}
function xmmClaim(k){var M=XMD(),o=null;XMM.forEach(function(x){if(x.k===k)o=x});if(!o||!xmmReady(o))return;M.got[k]=1;save.pearls+=o.p;persist();crumb('xmm:'+k);try{svSnd('gem');buzz([20,30])}catch(e){}
  banner(T('미션 보상을 받았어요!'),T('진주 ')+'+'+nf(o.p)+' · '+T('선물 상자 ')+'+'+o.c);xmBoxAdd(o.c);try{refreshHome(true)}catch(e){}xmRender()}

/* --- 선물 상자 모으기 --- */
var XMC=[{n:30,p:1000},{n:80,g:20},{n:150,a:'xm_holly'},{n:250,p:3000},{n:350,a:'pr_snowman'},{n:500,p:10000}]; /* 1.1.28: 350개 = 눈사람 짝꿍(펫) */
function xmBoxN(){return XM().box}
function xmBoxAdd(n){if(!(n>0)||!xmSeason())return;var o=XM(),b=o.box;o.box=b+n;persist();
  XMC.forEach(function(m){if(b<m.n&&b+n>=m.n)setTimeout(function(){banner(T('선물 상자 모으기'),nf(m.n)+T('개')+T(' · 크리스마스 이벤트에서 받아요'))},1400)});try{xmBarPaint()}catch(e){}}
function xmcGot(i){return XM().cg.indexOf(i)>=0}
function xmcClaim(i){var m=XMC[i];if(!m||xmcGot(i)||xmBoxN()<m.n)return;XM().cg.push(i);var sub=xmGive(m);crumb('xmc:'+i);try{svSnd('gem');buzz([20,30,40])}catch(e){}
  var an=m.a?(accById(m.a)||{name:''}).name:'';banner(m.a==='xm_holly'?T('왕관을 받았어요!'):T('선물 상자 선물을 받았어요!'),m.a?an:sub);if(m.a)setTimeout(function(){banner(an,m.a==='pr_snowman'?T('상점 › 꾸미기 › 펫에서 데려가요'):T('상점 › 꾸미기 › 모자에서 입혀요'))},1800);
  try{refreshHome(true)}catch(e){}xmRender();xmBarPaint()}
function xmAny(){if(!xmSeason())return false;if(xmAttCan())return true;for(var i=0;i<XMM.length;i++)if(xmmReady(XMM[i]))return true;for(var j=0;j<XMC.length;j++)if(!xmcGot(j)&&xmBoxN()>=XMC[j].n)return true;return false}

